import{_ as s,o as a,c as e,a6 as p}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"location 匹配规则","description":"五种修饰符、「记住最长前缀再试正则」的两阶段算法、^~ 与 = 的短路，以及嵌套 location。","frontmatter":{"title":"location 匹配规则","description":"五种修饰符、「记住最长前缀再试正则」的两阶段算法、^~ 与 = 的短路，以及嵌套 location。","source":"https://daiw.org/manual/nginx/location"},"headers":[],"relativePath":"manual/tools/nginx/location.md","filePath":"manual/tools/nginx/location.md"}'),t={name:"manual/tools/nginx/location.md"};function l(i,n,o,r,c,d){return a(),e("div",null,[...n[0]||(n[0]=[p(`<h1 id="location-匹配规则" tabindex="-1">location 匹配规则 <a class="header-anchor" href="#location-匹配规则" aria-label="Permalink to &quot;location 匹配规则&quot;">​</a></h1><p><code>location</code> 的匹配算法与 <a href="/Front2Full/manual/tools/nginx/request-processing"><code>server_name</code> 的四级优先级</a><strong>完全不同</strong>，是 nginx 配置里第二大混淆源。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    location [ = | ~ | ~* | ^~ ] uri { ... }</span></span>
<span class="line"><span>         location $variable { ... }</span></span>
<span class="line"><span>         location @name { ... }</span></span>
<span class="line"><span>上下文:  server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>六种形式：</p><table tabindex="0"><thead><tr><th>修饰符 / 形式</th><th>含义</th></tr></thead><tbody><tr><td>（无）</td><td><strong>前缀</strong>匹配</td></tr><tr><td><code>=</code></td><td><strong>精确</strong>匹配</td></tr><tr><td><code>~</code></td><td>正则，<strong>区分</strong>大小写</td></tr><tr><td><code>~*</code></td><td>正则，<strong>不分</strong>大小写</td></tr><tr><td><code>^~</code></td><td>前缀匹配，且<strong>命中后不再试正则</strong></td></tr><tr><td><code>$variable</code></td><td><strong>谓词 location</strong>（1.31.5 起），运行时求值非空且非 <code>&quot;0&quot;</code> 即命中</td></tr><tr><td><code>@name</code></td><td><strong>命名 location</strong>，只能内部跳转，不匹配外部请求</td></tr></tbody></table><h2 id="匹配算法" tabindex="-1">匹配算法 <a class="header-anchor" href="#匹配算法" aria-label="Permalink to &quot;匹配算法&quot;">​</a></h2><p>官方原文是理解这套规则的唯一可靠依据：</p><blockquote><p>To find location matching a given request, nginx <strong>first checks locations defined using the prefix strings</strong> (prefix locations). Among them, the location with the <strong>longest matching prefix is selected and remembered</strong>. Then <strong>regular expressions are checked, in the order of their appearance</strong> in the configuration file. The search of regular expressions <strong>terminates on the first match</strong>, and the corresponding configuration is used. <strong>If no match with a regular expression is found</strong> then the configuration of the prefix location <strong>remembered earlier</strong> is used.</p></blockquote><p>拆成步骤：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 遍历所有【前缀】location，找出匹配且【最长】的那个 → 记住它（先不用）</span></span>
<span class="line"><span>2. 按【配置文件中出现的顺序】逐个试【正则】location</span></span>
<span class="line"><span>3. 第一个匹配的正则 → 用它，结束</span></span>
<span class="line"><span>4. 没有正则匹配 → 用第 1 步记住的前缀 location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>核心要点：前缀比「长度」，正则比「顺序」。</strong> 前缀 location 在配置里的书写顺序完全不影响结果；正则 location 的顺序则决定一切。</p><h2 id="两个短路规则" tabindex="-1">两个短路规则 <a class="header-anchor" href="#两个短路规则" aria-label="Permalink to &quot;两个短路规则&quot;">​</a></h2><h3 id="——-前缀命中就不试正则" tabindex="-1"><code>^~</code> —— 前缀命中就不试正则 <a class="header-anchor" href="#——-前缀命中就不试正则" aria-label="Permalink to &quot;\`^~\` —— 前缀命中就不试正则&quot;">​</a></h3><blockquote><p>If the longest matching prefix location has the <code>^~</code> modifier then <strong>regular expressions are not checked</strong>.</p></blockquote><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location ^~ /images/ {</span></span>
<span class="line"><span>    root /data;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>location ~* \\.(gif|jpg|png)$ {</span></span>
<span class="line"><span>    expires 30d;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>请求 <code>/images/logo.png</code>：前缀 <code>^~ /images/</code> 是最长匹配且带 <code>^~</code> → <strong>直接用它，正则块被跳过</strong>，<code>expires 30d</code> 不生效。</p><p>典型用途：静态资源目录要整体走一套配置，不希望被后面的通用正则截走。</p><h3 id="——-精确匹配立即结束" tabindex="-1"><code>=</code> —— 精确匹配立即结束 <a class="header-anchor" href="#——-精确匹配立即结束" aria-label="Permalink to &quot;\`=\` —— 精确匹配立即结束&quot;">​</a></h3><blockquote><p>Also, using the <code>=</code> modifier it is possible to define an <strong>exact match</strong> of URI and location. If an exact match is found, <strong>the search terminates</strong>.</p></blockquote><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location = / {</span></span>
<span class="line"><span>    # 只匹配 &quot;/&quot;，不匹配 &quot;/index.html&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>=</code> 是<strong>最快</strong>的：命中即停，连「记住最长前缀」那一步都省了。高频且路径固定的端点（<code>/</code>、<code>/health</code>、<code>/favicon.ico</code>）用它能省下遍历开销。</p><h2 id="完整优先级" tabindex="-1">完整优先级 <a class="header-anchor" href="#完整优先级" aria-label="Permalink to &quot;完整优先级&quot;">​</a></h2><p>综合起来：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. location = /exact          精确匹配 → 命中即停</span></span>
<span class="line"><span>2. location ^~ /prefix/       最长前缀且带 ^~ → 命中即停（跳过正则与谓词）</span></span>
<span class="line"><span>3. location ~ /regex          正则，按【配置顺序】，第一个命中即停</span></span>
<span class="line"><span>   location ~* /regex</span></span>
<span class="line"><span>4. location $predicate        谓词 location（1.31.5+），按【配置顺序】，第一个非空且非 &quot;0&quot; 即停</span></span>
<span class="line"><span>5. location /prefix           最长前缀（前面都没命中时的兜底）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>注意第 2 与第 4 的关系：<strong><code>^~</code> 参与的是同一轮「最长前缀」竞争</strong>。它不是「优先级更高的前缀」，而是「如果我赢了最长前缀，就别再试正则」。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location ^~ /a/    { }      # 前缀长度 3</span></span>
<span class="line"><span>location    /a/b/  { }      # 前缀长度 5 ← 更长，这个赢</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>请求 <code>/a/b/c</code> 命中的是 <code>/a/b/</code>（更长），<code>^~</code> 的短路效果不生效，正则照常被试。</p><h2 id="命名-location" tabindex="-1">命名 location <a class="header-anchor" href="#命名-location" aria-label="Permalink to &quot;命名 location&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location / {</span></span>
<span class="line"><span>    try_files $uri $uri/ @backend;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>location @backend {</span></span>
<span class="line"><span>    proxy_pass http://app_servers;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>@name</code> <strong>不参与请求匹配</strong>，只能被 <a href="/Front2Full/manual/tools/nginx/root-alias"><code>try_files</code></a>、<code>error_page</code> 等指令内部跳转过来。用于把「兜底逻辑」抽出来复用。</p><h2 id="嵌套-location" tabindex="-1">嵌套 location <a class="header-anchor" href="#嵌套-location" aria-label="Permalink to &quot;嵌套 location&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /api/ {</span></span>
<span class="line"><span>    proxy_pass http://backend;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location /api/v1/legacy/ {</span></span>
<span class="line"><span>        proxy_pass http://legacy_backend;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>location</code> 的上下文是 <code>server, location</code>——<strong>可以嵌套</strong>。嵌套的 location 只在外层匹配成功后才参与匹配。</p><p>嵌套主要用于组织结构，性能上与平铺没有本质差别。<strong>注意继承规则</strong>：嵌套 location 会从外层 location 继承配置，<a href="/Front2Full/manual/tools/nginx/contexts">数组型指令的覆盖问题</a>同样适用。</p><h2 id="一个完整例子" tabindex="-1">一个完整例子 <a class="header-anchor" href="#一个完整例子" aria-label="Permalink to &quot;一个完整例子&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    # 1. 精确：命中即停，最快</span></span>
<span class="line"><span>    location = / {</span></span>
<span class="line"><span>        return 200 &quot;home\\n&quot;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 2. ^~ 前缀短路：静态资源整体接管，不被下面的正则截走</span></span>
<span class="line"><span>    location ^~ /static/ {</span></span>
<span class="line"><span>        root    /var/www;</span></span>
<span class="line"><span>        expires 30d;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 3. 正则：按顺序试。这个在前，先匹配</span></span>
<span class="line"><span>    location ~* \\.(js|css)$ {</span></span>
<span class="line"><span>        expires 7d;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 4. 正则：上面没中才轮到这个</span></span>
<span class="line"><span>    location ~* \\.(png|jpg|gif)$ {</span></span>
<span class="line"><span>        expires 30d;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 5. 前缀：兜底</span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span>        try_files $uri $uri/ @app;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location @app {</span></span>
<span class="line"><span>        proxy_pass http://backend;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br></div></div><p>对照几个请求：</p><table tabindex="0"><thead><tr><th>请求</th><th>命中</th><th>原因</th></tr></thead><tbody><tr><td><code>/</code></td><td>1</td><td>精确匹配</td></tr><tr><td><code>/index.html</code></td><td>5</td><td>精确不中；前缀最长是 <code>/</code>；无正则匹配</td></tr><tr><td><code>/static/app.js</code></td><td>2</td><td><code>^~ /static/</code> 最长前缀 + 短路，<strong>正则 3 被跳过</strong></td></tr><tr><td><code>/assets/app.js</code></td><td>3</td><td>前缀最长是 <code>/</code>；正则 3 先命中</td></tr><tr><td><code>/img/a.png</code></td><td>4</td><td>正则 3 不中，正则 4 中</td></tr></tbody></table><p><strong>注意 <code>/static/app.js</code> 那行</strong>——直觉上「js 文件应该走正则 3」，但 <code>^~</code> 让它停在了 2。这正是 <code>^~</code> 的意义，也是它容易造成意外的地方。</p><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><p>不确定命中哪个 location 时，最直接的办法是在每个块里加标记：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location ^~ /static/ {</span></span>
<span class="line"><span>    add_header X-Debug-Location &quot;static&quot; always;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>或者开 <code>error_log ... debug;</code>（需<a href="/Front2Full/manual/tools/nginx/core-module">编译带 <code>--with-debug</code></a>），日志里会打印完整的 location 选择过程。</p><p>下一篇：<a href="/Front2Full/manual/tools/nginx/root-alias">root、alias 与 try_files</a>。</p>`,45)])])}const h=s(t,[["render",l]]);export{u as __pageData,h as default};
